        return Err(FoldErr::Shape);
    }

    let mut low = a[0];
    let mut high = a[0];
    let mut has_absent = false;
    for (value, present) in a.iter().zip(b.iter()) {
        low = low.min(*value);
        high = high.max(*value);
        has_absent |= *present == 0;
    }

    Ok(Mark {
        low,
        high,
        has_absent,
    })
}
